#!/usr/bin/env python3
"""Process GitHub issues using Claude API."""

import os
import sys
import json

import requests
from anthropic import Anthropic

GITHUB_API_URL = "https://api.github.com"
REPO = os.getenv("GITHUB_REPOSITORY")
ISSUE_NUMBER = os.getenv("GITHUB_EVENT_NUMBER")
GITHUB_TOKEN = os.getenv("GITHUB_TOKEN")
ANTHROPIC_API_KEY = os.getenv("ANTHROPIC_API_KEY")

headers = {
    "Authorization": f"token {GITHUB_TOKEN}",
    "Accept": "application/vnd.github.v3+json",
}


def get_issue_details() -> dict:
    """Fetch issue details from GitHub API."""
    if not ISSUE_NUMBER:
        print("Warning: ISSUE_NUMBER not set")
        return {}

    url = f"{GITHUB_API_URL}/repos/{REPO}/issues/{ISSUE_NUMBER}"
    resp = requests.get(url, headers=headers)
    resp.raise_for_status()
    return resp.json()


def post_issue_comment(comment_text: str):
    """Post a comment on the issue."""
    if not ISSUE_NUMBER:
        print("Warning: ISSUE_NUMBER not set, skipping comment")
        return

    url = f"{GITHUB_API_URL}/repos/{REPO}/issues/{ISSUE_NUMBER}/comments"
    data = {"body": comment_text}
    resp = requests.post(url, json=data, headers=headers)
    resp.raise_for_status()
    print(f"Posted issue comment: {resp.json()['html_url']}")


def analyze_issue_with_claude(issue: dict) -> dict:
    """Use Claude to analyze the issue."""
    client = Anthropic()

    issue_text = f"""
Title: {issue.get('title', 'N/A')}
Author: {issue.get('user', {}).get('login', 'N/A')}
Body:
{issue.get('body', 'No description')}
"""

    message = client.messages.create(
        model="claude-haiku-4-5-20251001",
        max_tokens=1024,
        system="""You are a helpful GitHub issue assistant. Analyze the issue and provide:
1. Summary of the issue
2. Potential causes or root cause analysis
3. Suggested solutions or next steps
4. Whether this is a bug, feature request, or documentation issue
5. Priority level (low/medium/high)

Format as markdown with clear sections.""",
        messages=[{"role": "user", "content": issue_text}],
    )

    response_text = message.content[0].text

    return {
        "analysis": response_text,
        "issue_type": extract_issue_type(response_text),
        "priority": extract_priority(response_text),
    }


def extract_issue_type(text: str) -> str:
    """Extract issue type from Claude's response."""
    if "bug" in text.lower():
        return "bug"
    elif "feature" in text.lower():
        return "enhancement"
    elif "documentation" in text.lower():
        return "documentation"
    return "general"


def extract_priority(text: str) -> str:
    """Extract priority from Claude's response."""
    if "high" in text.lower():
        return "high"
    elif "medium" in text.lower():
        return "medium"
    return "low"


def add_labels(labels: list):
    """Add labels to the issue."""
    if not ISSUE_NUMBER or not labels:
        return

    url = f"{GITHUB_API_URL}/repos/{REPO}/issues/{ISSUE_NUMBER}/labels"
    data = {"labels": labels}
    resp = requests.post(url, json=data, headers=headers)
    if resp.status_code in [200, 201]:
        print(f"Added labels: {labels}")


def main():
    """Main function."""
    if not ANTHROPIC_API_KEY:
        print("Error: ANTHROPIC_API_KEY not set")
        sys.exit(1)

    if not GITHUB_TOKEN:
        print("Error: GITHUB_TOKEN not set")
        sys.exit(1)

    print("Fetching issue details...")
    issue = get_issue_details()
    if not issue:
        print("No issue found or ISSUE_NUMBER not set")
        return

    print("Analyzing issue with Claude...")
    analysis = analyze_issue_with_claude(issue)

    print("\n=== Claude Issue Analysis ===")
    print(analysis["analysis"])
    print("=" * 28)
    print(f"Issue Type: {analysis['issue_type']}")
    print(f"Priority: {analysis['priority']}")

    print("\nPosting analysis as issue comment...")
    comment_body = f"""## 🤖 Claude Analysis

{analysis['analysis']}

**Classification:**
- Type: `{analysis['issue_type']}`
- Priority: `{analysis['priority']}`

---
*This analysis was automatically generated by Claude*"""
    post_issue_comment(comment_body)

    print("\nAdding labels...")
    labels = ["claude-reviewed", analysis["issue_type"], analysis["priority"]]
    add_labels(labels)


if __name__ == "__main__":
    main()
